import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import requests


class DatadogLogQueryClient:
    def __init__(self, api_key: Optional[str] = None, app_key: Optional[str] = None, site: Optional[str] = None) -> None:
        self.api_key = api_key or os.environ["DATADOG_API_KEY"]
        self.app_key = app_key or os.environ["DATADOG_APP_KEY"]
        self.site = site or os.environ.get("DATADOG_SITE", "datadoghq.com")
        self.base_url = f"https://api.{self.site}"
        self.session = requests.Session()
        self.session.headers.update(
            {
                "DD-API-KEY": self.api_key,
                "DD-APPLICATION-KEY": self.app_key,
                "Content-Type": "application/json",
                "Accept": "application/json",
            }
        )

    @staticmethod
    def _iso_z(dt: datetime) -> str:
        return dt.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")

    @staticmethod
    def _escape_value(value: Any) -> str:
        s = str(value)
        if any(ch.isspace() for ch in s) or '"' in s or ":" in s:
            s = s.replace("\\", "\\\\").replace('"', '\\"')
            return f'"{s}"'
        return s

    def _build_query(
        self,
        field_filters: Optional[Dict[str, Any]] = None,
        text_query: Optional[str] = None,
    ) -> str:
        parts: List[str] = []
        if text_query:
            parts.append(f"({text_query})")
        for field, value in (field_filters or {}).items():
            parts.append(f"@{field}:{self._escape_value(value)}")
        return " AND ".join(parts) if parts else "*"

    def search_recent_logs(
        self,
        field_filters: Optional[Dict[str, Any]] = None,
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None,
        minutes_ago: int = 15,
        limit: int = 100,
        sort: str = "timestamp",
        order: str = "desc",
        text_query: Optional[str] = None,
        indexes: Optional[List[str]] = None,
    ) -> List[Dict[str, Any]]:
        now = datetime.now(timezone.utc)
        start = start_time or (now - timedelta(minutes=minutes_ago))
        end = end_time or now
        query = self._build_query(field_filters=field_filters, text_query=text_query)

        payload = {
            "filter": {
                "from": self._iso_z(start),
                "to": self._iso_z(end),
                "query": query,
            },
            "sort": f"{'-' if order.lower() == 'desc' else ''}{sort}",
            "page": {"limit": limit},
        }
        if indexes:
            payload["filter"]["indexes"] = indexes

        resp = self.session.post(f"{self.base_url}/api/v2/logs/events/search", json=payload, timeout=30)
        resp.raise_for_status()
        body = resp.json()

        results: List[Dict[str, Any]] = []
        for item in body.get("data", []):
            attrs = item.get("attributes", {})
            results.append(
                {
                    "id": item.get("id"),
                    "timestamp": attrs.get("timestamp"),
                    "message": attrs.get("message"),
                    "service": attrs.get("attributes", {}).get("service"),
                    "status": attrs.get("status"),
                    "host": attrs.get("host"),
                    "tags": attrs.get("tags", []),
                    "raw": item,
                }
            )
        return results
